import numpy as np, driver, math
def cg(r, t, vx, vy, wz, freq, ath, acalf, ahip):
    q=r._home_q.copy(); omega=2*math.pi*freq
    ph={'FR':0.0,'FL':math.pi,'RR':math.pi,'RL':0.0}
    for i,leg in enumerate(r._leg_order):
        phase=omega*t+ph[leg]; c=math.cos(phase); s=math.sin(phase)
        swing=max(0.0,s); b=i*3; left=1.0 if leg[1]=='L' else -1.0; front=1.0 if leg[0]=='F' else -1.0
        drive = vx - wz*0.28*left
        q[b+1]+= ath*drive*c          # zero-mean propulsion (cos)
        q[b+2]+= -acalf*swing         # lift foot during swing
        q[b+0]+= ahip*vy*c*front
    return np.clip(q,r._joint_lo,r._joint_hi)
def run(vx,vy,wz,ath,secs=3.0):
    r=driver.build(); ts=float(r.model.opt.timestep); freq=2.5; gp=1.0/freq; gt=0.0
    t0=float(r.data.time); vxs=[];wzs=[];vys=[]
    while float(r.data.time)-t0<secs:
        q=cg(r,gt,vx,vy,wz,freq,ath,0.35,0.15)
        r.apply_pd_posture(q); r.step(1); gt=(gt+ts)%gp
        if float(r.data.time)-t0>secs-1.0:
            tw=r.get_base_twist(); vb=tw['linear_body_yaw_m_s']
            vxs.append(float(vb[0]));vys.append(float(vb[1]));wzs.append(float(tw['yaw_rate_rad_s']))
    return (round(np.mean(vxs),3),round(np.mean(vys),3),round(np.mean(wzs),3),[round(x,2) for x in r._roll_pitch()],round(r.get_body_height(),3))
